// ── Build the story prompt from the 15 quiz answers ──────────────
// The crown jewel. Everything the reading is depends on this prompt.

const MIN_WORDS = 400;
const MAX_WORDS = 550;

const KEYS = [
  'name', 'city', 'spot', 'partner', 'people', 'desire', 'area', 'milestone',
  'milestone_location', 'proof_number', 'work_vision', 'success_place',
  'sensory_detail', 'good_news_caller', 'scarcity_habit',
];

const raw = $input.first().json;
const body = raw.body ?? raw;
const src = body.profile ?? body;

// Never trust the client: known keys only, control chars stripped, length capped.
const profile = {};
for (const k of KEYS) {
  let v = src[k];
  if (typeof v !== 'string') v = '';
  v = v.replace(/[\u0000-\u001F\u007F]/g, '').replace(/\s+/g, ' ').trim();
  profile[k] = v.slice(0, 400);
}

if (!profile.name && !profile.desire) {
  throw new Error('Need at least a name or a desire to write from.');
}

const AREA_NOTES = {
  money:   'Tone: steady and unbothered. Money appears as ease and margin, never as bragging.',
  career:  'Tone: competent and calm. Work is craft that finally fits.',
  love:    'Tone: warm and close. Small domestic gestures carry the weight.',
  home:    'Tone: rooted and sensory. The rooms themselves do the talking.',
  freedom: 'Tone: spacious and unhurried. Time is the luxury on display.',
  health:  'Tone: physical and clear. The body feels different than it used to.',
};
const areaNote = AREA_NOTES[(profile.area || '').toLowerCase()] || 'Tone: steady, warm, unhurried.';

const system = [
  'You write a single first-person, present-tense narrative in which the reader is ALREADY living the life they described — it has happened, it is happening now, today. Not a prediction, not a fantasy. A quiet, real morning in their achieved life.',
  '',
  'Rules:',
  '- First person, present tense throughout. Never "you will," never "imagine," never "one day."',
  '- Weave the real names, places, and numbers from their profile in naturally, the way a person thinks about their own life. Don\'t list them — let them surface in an ordinary moment.',
  '- Include one CONTRAST beat: a short reflection on how they used to act from scarcity ("Three years ago, I would have…"), then how effortless it is now. This is the emotional center. Do not skip it.',
  '- Ground everything in small mundane sensory details — a phone buzzing, a glass of wine, a framed photo, a parking text. The ordinariness makes it real.',
  '- Use concrete numbers where given. Counted success feels true; vague abundance feels fake.',
  '- Short, calm cadence suitable for slow narration. No mysticism, no exclamation marks, no advice, no addressing the reader as "you."',
  '- Write in plain paragraphs separated by a blank line. No headings, no lists, no title.',
  `- ${MIN_WORDS}–${MAX_WORDS} words. End on a quiet, grounded, human moment — not a triumphant one.`,
  '',
  'You\'ll receive the profile as JSON. Return ONLY the story text.',
].join('\n');

const user = [
  JSON.stringify(profile, null, 2),
  '',
  areaNote,
  '',
  `Length: ${MIN_WORDS}–${MAX_WORDS} words — six or seven full paragraphs. Do not stop short of ${MIN_WORDS} words. Remember the contrast beat.`,
].join('\n');

return [{ json: { system, user, profile } }];

// ── Tidy the model output and split it for the line-by-line reveal ──

const res = $input.first().json;
const profile = $('Build Prompt').first().json.profile;

let story = (res.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('')
  .trim();

// Strip anything the model wrapped it in.
story = story
  .replace(/^```[a-z]*\s*/i, '')
  .replace(/\s*```$/i, '')
  .replace(/^(here(?:'s| is)[^\n]*:|story:)\s*/i, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (story.split(/\s+/).filter(Boolean).length < 120) {
  throw new Error('Model returned too little text to be a reading.');
}

// Paragraphs, with long ones split at sentence boundaries so no single
// block dumps eight lines onto the reveal screen at once.
const countWords = (s) => (s.trim().match(/\S+/g) || []).length;
const MAX_LINE_WORDS = 55;
const lines = [];

for (const para of story.split(/\n\s*\n/).map((s) => s.trim()).filter(Boolean)) {
  if (countWords(para) <= MAX_LINE_WORDS) { lines.push(para); continue; }
  const sentences = para.match(/[^.!?]+[.!?]+["']?\s*|[^.!?]+$/g) || [para];
  let buf = '';
  for (const s of sentences) {
    if (buf && countWords(buf + s) > MAX_LINE_WORDS) { lines.push(buf.trim()); buf = s; }
    else buf += s;
  }
  if (buf.trim()) lines.push(buf.trim());
}

return [{
  json: {
    story,
    lines,
    words: countWords(story),
    model: res.model || 'claude',
    name: profile.name || '',
  },
}];

// ── Resolve the voice and sanity-check the text ─────────────────────
// Replace these with voice IDs you have actually auditioned — the voice
// is half the product. https://elevenlabs.io/app/voice-library

const VOICES = {
  calm:      'EXAVITQu4vr4xnSDxMaL', // Sarah   — soft, unhurried
  warm:      'XrExE9yKIg1WjnnlVkGX', // Matilda — warm, close-mic
  confident: 'pFZP5JQG7iQjIQuC4Bku', // Lily    — clear, grounded
};
const DEFAULT_VOICE = 'calm';
const MAX_CHARS = 5000; // ElevenLabs per-request ceiling

const raw = $input.first().json;
const body = raw.body ?? raw;

let text = String(body.text || '').trim();
if (!text) throw new Error('Nothing to say.');
if (text.length > MAX_CHARS) text = text.slice(0, MAX_CHARS);

const key = String(body.voice || DEFAULT_VOICE).toLowerCase().replace(/[^a-z_]/g, '');
const voiceId = VOICES[key] || VOICES[DEFAULT_VOICE];

return [{ json: { text, voiceId, voice: VOICES[key] ? key : DEFAULT_VOICE } }];
